// bslib value box component
//
// Value boxes display a single metric with an icon and optional
// showcase area. They have their own color system.

.bslib-value-box {
  // Value boxes use a custom color system independent of Bootstrap's
  // body-color cascade. This allows value boxes to have their own
  // foreground/background pairs (e.g., white text on colored bg).

  --bslib-value-box-shadow: #{$box-shadow-sm};

  display: flex;
  flex-direction: row;
  align-items: stretch;
  border: none;
  border-radius: var(--#{$prefix}card-border-radius);
  box-shadow: var(--bslib-value-box-shadow);
  overflow: hidden;

  color: var(--bslib-color-fg, inherit);
  // value-box uses its own --bslib-color-fg, not body-color
  // When --bslib-color-fg is not set, falls back to inherit
  // The inherit fallback works IF the ancestor has body-color

  background-color: var(--bslib-color-bg, var(--#{$prefix}card-bg));

  .value-box-title {
    font-size: 0.85rem;
    font-weight: 500;
    opacity: 0.8;
    margin-bottom: 0.25rem;
  }

  .value-box-value {
    font-size: 1.75rem;
    font-weight: 600;
    line-height: 1.2;
  }
}
